validator:
function validate([head]) {
  if (!Array.isArray(head) || head.length < 1 || head.length > 50) return 'The list needs 1 to 50 values.';
  if (head.some(v => !Number.isInteger(v) || v < 1 || v > 50)) return 'Each value is a whole number from 1 to 50.';
  return null;
}

adapter:
function adapt(input, solve, kit) {
  const [values] = input;
  // Link the nodes both ways: next comes from listNodes, prev is added here.
  const nodes = kit.listNodes(values);
  nodes.forEach((node, i) => {
    node.prev = i > 0 ? nodes[i - 1] : null;
  });
  const result = solve(nodes[0]);
  if (!Array.isArray(result)) throw new Error('Return an array of the values, from the head to the last node.');
  return result;
}

reference:
function toArray(head) {
  const values = [];
  let node = head;
  while (node !== null) {
    values.push(node.val);
    node = node.next;
  }
  return values;
}

brute:
function toArray(head) {
  // Run to the last node, collect the values walking back along prev, then reverse them.
  let tail = head;
  while (tail.next !== null) tail = tail.next;
  const backwards = [];
  for (let node = tail; node !== null; node = node.prev) backwards.push(node.val);
  return backwards.reverse();
}

generator:
function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? 50 : 1 + pick(8);
  // A narrow range repeats values; the full range reaches 1 and 50.
  const top = size === 'large' ? 50 : [2, 5, 50][pick(3)];
  return [Array.from({ length: n }, () => 1 + pick(top))];
}
